{"code":"def transform(grid):
    h=len(grid); w=len(grid[0])
    pts=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0: pts.append((r,grid[r][c]))
    pts.sort()
    if not pts: return [row[:] for row in grid]
    out=[[0]*w for _ in range(h)]
    lines={0, h-1}
    for r,col in pts: lines.add(r)
    for r in range(h):
        if r in lines:
            # top/bottom use endpoint colors; marker lines their own
            if r==0: col=pts[0][1]
            elif r==h-1: col=pts[-1][1]
            else:
                col=next((x[1] for x in pts if x[0]==r), pts[-1][1])
            for c in range(w): out[r][c]=col
        else:
            # color of nearest marker row; ties favor earlier marker
            best=min(pts, key=lambda x:(abs(x[0]-r), x[0]))
            col=best[1]
            out[r][0]=out[r][-1]=col
    return out"}

